import numpy as np
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
import os
from .utils import calculate_log2fc, _get_filter_for_motif, get_custom_motif_presence_in_library

# %% ../nbs/02_plotting.ipynb #8d97e736
def plot_motif_analysis(
    counts_df:pd.DataFrame, # read counts, one row per insert, one column per sample
    sample_col:str, # the recipient sample to plot
    ref_col:str, # the input-library column it is compared with
    motifs:pd.DataFrame|None, # motifs to highlight, in a 'motif' column (`find_restricted_motifs`)
    left_context:str, # vector sequence 5' of the insert
    right_context:str, # vector sequence 3' of the insert
    title_main:str|None=None, # figure title; default "Motif Analysis: <sample_col> vs <ref_col>"
    pseudocount:float=1, # added to the counts per million of the scatter, before the log
    log2fc_count_threshold:int=20, # `count_threshold` of `calculate_log2fc`, for the histogram
    log2fc_pseudocount:float=1, # `pseudocount` of `calculate_log2fc`, for the histogram
    figsize:tuple=(12, 6), # figure size, in inches
    save_filename:str|None=None, # also save the figure to this file, at 300 dpi
    distribution_plot_log_xscale:bool=False, # log scale on the histogram's x axis
)->tuple: # `(fig, axes)`; `(None, None)` when `counts_df` is empty or lacks either column
    "Donor against recipient counts with each motif's carriers highlighted, beside their log2FC."

    if not isinstance(counts_df, pd.DataFrame) or counts_df.empty: return None, None
    if not all(col in counts_df.columns for col in [sample_col, ref_col]): return None, None
    
    if motifs is None: motifs = pd.DataFrame(columns=['motif'])
    elif not isinstance(motifs, pd.DataFrame): return None, None
    if not motifs.empty and 'motif' not in motifs.columns:
        motifs = pd.DataFrame(columns=['motif'])

    # Auto-generate title_main if it's None
    if title_main is None:
        title_main = f"Motif Analysis: {sample_col} vs {ref_col}"

    # --- Define Color Palette ---
    unique_plot_motifs = []
    if 'motif' in motifs.columns and not motifs.empty:
        unique_plot_motifs = motifs['motif'].dropna().unique().tolist()

    color_map = {'All Sequences': 'grey'} 
    palette_name = "tab10" 
    if len(unique_plot_motifs) > 10:
        palette_name = "tab20" 
        if len(unique_plot_motifs) > 20:
            print(f"Warning: Number of unique motifs ({len(unique_plot_motifs)}) exceeds typical palette size. Colors may repeat.")
    motif_colors = sns.color_palette(palette_name, n_colors=len(unique_plot_motifs))
    for i, motif_str in enumerate(unique_plot_motifs):
        color_map[motif_str] = motif_colors[i]
    hue_order = ['All Sequences'] + unique_plot_motifs

    # --- Data for Scatter Plot ---
    plot_df_scatter = counts_df.copy()
    plot_df_scatter['sample_numeric'] = pd.to_numeric(plot_df_scatter[sample_col], errors='coerce').fillna(0)
    plot_df_scatter['ref_numeric'] = pd.to_numeric(plot_df_scatter[ref_col], errors='coerce').fillna(0)
    total_sample_scatter = plot_df_scatter['sample_numeric'].sum()
    total_ref_scatter = plot_df_scatter['ref_numeric'].sum()
    
    if total_sample_scatter == 0 or total_ref_scatter == 0:
        plot_df_scatter['y_plot_values'] = plot_df_scatter['sample_numeric'] + pseudocount
        plot_df_scatter['x_plot_values'] = plot_df_scatter['ref_numeric'] + pseudocount
        norm_label_suffix = f"(Counts + {pseudocount})"
    else:
        plot_df_scatter['y_plot_values'] = (plot_df_scatter['sample_numeric'] / total_sample_scatter * 1e6) + pseudocount
        plot_df_scatter['x_plot_values'] = (plot_df_scatter['ref_numeric'] / total_ref_scatter * 1e6) + pseudocount
        norm_label_suffix = f"(CPM + {pseudocount})"

    # --- Data for Histogram Plot (Log2FC) ---
    df_for_log2fc = counts_df[[sample_col, ref_col]].copy()
    log2fc_df = calculate_log2fc(df_for_log2fc, 
                                 reference_column=ref_col, 
                                 count_threshold=log2fc_count_threshold, 
                                 pseudocount=log2fc_pseudocount)

    hist_data_list = []
    if log2fc_df is not None and not log2fc_df.empty and sample_col in log2fc_df.columns:
        for val in log2fc_df[sample_col].dropna():
            hist_data_list.append({'value': val, 'group': 'All Sequences'})

    # --- Plotting Setup ---
    fig, axes = plt.subplots(1, 2, figsize=figsize)
    if title_main: # Check if title_main is not an empty string or None after potential auto-generation
        fig.suptitle(title_main, fontsize=18, y=1.02)
    ax_scatter, ax_dist = axes[0], axes[1]

    # --- Subplot 1: Scatter Plot ---
    ax_scatter.scatter(plot_df_scatter['x_plot_values'], plot_df_scatter['y_plot_values'],
                       color=color_map['All Sequences'], alpha=0.5, s=10, label='All Sequences')
    
    for motif_str_to_plot in unique_plot_motifs:
        flt_scatter = _get_filter_for_motif(plot_df_scatter, motif_str_to_plot, left_context, right_context)
        if not flt_scatter.any(): continue

        df_flt_scatter = plot_df_scatter.loc[flt_scatter]
        if not df_flt_scatter.empty:
            motif_color = color_map.get(motif_str_to_plot, 'blue') 
            ax_scatter.scatter(df_flt_scatter['x_plot_values'], df_flt_scatter['y_plot_values'],
                               color=motif_color, alpha=0.5, s=25, label=motif_str_to_plot)

            if log2fc_df is not None and not log2fc_df.empty and sample_col in log2fc_df.columns:
                motif_sequences_in_log2fc = log2fc_df.index.intersection(plot_df_scatter.index[flt_scatter])
                if not motif_sequences_in_log2fc.empty:
                    motif_log2fc_values = log2fc_df.loc[motif_sequences_in_log2fc, sample_col].dropna()
                    for val in motif_log2fc_values:
                        hist_data_list.append({'value': val, 'group': motif_str_to_plot})
    
    ax_scatter.loglog()
    ax_scatter.set_xlabel(f"{ref_col} {norm_label_suffix}, log scale")
    ax_scatter.set_ylabel(f"{sample_col} {norm_label_suffix}, log scale")
    ax_scatter.legend()
    ax_scatter.grid(True, which="both", ls="--", alpha=0.4)
    ax_scatter.set_title("Sequence Motif Abundance Comparison", fontsize=12)

    # --- Subplot 2: Distribution Plot (Histogram of Log2FC) ---
    if hist_data_list:
        hist_df = pd.DataFrame(hist_data_list)
        sns.histplot(data=hist_df, x='value', hue='group', hue_order=hue_order,
                     palette=color_map, 
                     ax=ax_dist, 
                     stat="density", 
                     common_norm=False, 
                     log_scale=(distribution_plot_log_xscale), 
                     multiple="layer", element="bars", kde=False, bins="auto")
        ax_dist.set_xlabel(f"log2 Fold Change ({sample_col} / {ref_col})")
        ax_dist.set_ylabel("Density") 
        ax_dist.set_title("Distribution of log2 Fold Change by Motif", fontsize=12)
        ax_dist.grid(True, axis='y', ls='--', alpha=0.5)
    else:
        ax_dist.text(0.5, 0.5, "No Log2FC data for distribution.",
                     horizontalalignment='center', verticalalignment='center',
                     transform=ax_dist.transAxes, color='red')
        ax_dist.set_title("Distribution of log2 Fold Change by Motif", fontsize=12)

    fig.tight_layout(pad=2.0)

    if save_filename:
        fig.savefig(save_filename, bbox_inches='tight', dpi=300)
    return fig, axes

# %% ../nbs/02_plotting.ipynb #ce39ffcd
_CB_PALETTE = ["#F0A226", "#0A795B", "#800074"]

def plot_motif_depletion(
    counts_df:pd.DataFrame, # read counts, one row per insert, one column per sample
    sample_col:str, # the recipient sample to plot
    ref_col:str, # the input-library column it is compared with
    motif_list:list, # motifs to colour by, in IUPAC letters and/or bracketed classes
    left_context:str, # vector sequence 5' of the insert
    right_context:str, # vector sequence 3' of the insert
    pseudocount:float=1, # added to the counts per million, before the log
    palette:list=_CB_PALETTE, # one colour per motif, at least as many as `motif_list`
):
    "Log-log plot of one sample's counts against the reference, coloured by the motifs you name."
    from plotnine import (
        aes, element_blank, element_text, geom_abline, geom_point, ggplot,
        guide_legend, guides, labs, scale_color_manual, scale_x_log10,
        scale_y_log10, theme, theme_classic,
    )

    if len(motif_list) > len(palette):
        raise ValueError(f"{len(motif_list)} motifs but only {len(palette)} colors in palette; "
                         "pass a longer palette.")

    motif_presence_df = get_custom_motif_presence_in_library(
        counts_df.index.tolist(), left_context, right_context, motif_list
    )

    plot_df = counts_df.copy()
    plot_df["sample_numeric"] = pd.to_numeric(plot_df[sample_col], errors="coerce").fillna(0)
    plot_df["ref_numeric"] = pd.to_numeric(plot_df[ref_col], errors="coerce").fillna(0)

    total_sample = plot_df["sample_numeric"].sum()
    total_ref = plot_df["ref_numeric"].sum()

    plot_df["y_plot_values"] = (plot_df["sample_numeric"] / total_sample * 1e6) + pseudocount
    plot_df["x_plot_values"] = (plot_df["ref_numeric"] / total_ref * 1e6) + pseudocount

    plot_df["Motif_Category"] = "All Sequences"
    for motif in motif_list:
        plot_df.loc[motif_presence_df[motif].values, "Motif_Category"] = motif

    df_background = plot_df[plot_df["Motif_Category"] == "All Sequences"].copy()
    df_motifs = plot_df[plot_df["Motif_Category"] != "All Sequences"].copy()
    df_motifs["Motif_Category"] = pd.Categorical(df_motifs["Motif_Category"], categories=motif_list)

    log10_labels = lambda l: [f"$10^{{{int(np.log10(x))}}}$" if x > 0 else "0" for x in l]

    p = (
        ggplot()
        + geom_point(df_background, aes(x="x_plot_values", y="y_plot_values"),
                     color="#B0B0B0", alpha=0.3, size=1, stroke=0)
        + geom_point(df_motifs, aes(x="x_plot_values", y="y_plot_values", color="Motif_Category"),
                     alpha=0.9, size=2, stroke=0)
        + geom_abline(intercept=0, slope=1, linetype="dashed", color="black", alpha=0.6, size=0.5)
        + scale_x_log10(labels=log10_labels)
        + scale_y_log10(labels=log10_labels)
        + scale_color_manual(values=list(palette), name="Candidate sites")
        + guides(color=guide_legend(override_aes={"size": 3, "alpha": 1}))
        + labs(x="Donor (Normalised plasmid counts)", y="Recipient (Normalised plasmid counts)")
        + theme_classic()
        + theme(
            text=element_text(color="black"),
            axis_title=element_text(size=12),
            axis_text=element_text(size=10),
            legend_position=(0.85, 0.2),
            legend_background=element_blank(),
            legend_key=element_blank(),
            legend_title=element_text(size=10),
            legend_text=element_text(size=9),
        )
    )
    return p
